<?php
namespace Delnavazan\Platform\Portals;

final class PortalPublicActionService {
    public function renderAbsenceConfirmation(string $handle,string $token):array { $row=(new PortalCapabilityService())->verify($handle,$token,PortalRule::ABSENCE);$confirmation=bin2hex(random_bytes(32));global $wpdb;$now=gmdate('Y-m-d H:i:s');$wpdb->insert($wpdb->prefix.'dzn_portal_public_action_events',array('uid'=>substr(hash('sha256',wp_generate_uuid4()),0,26),'capability_id'=>(int)$row->id,'lesson_id'=>(int)$row->lesson_id,'purpose'=>PortalRule::ABSENCE,'action_sequence'=>(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(action_sequence),0)+1 FROM {$wpdb->prefix}dzn_portal_public_action_events WHERE capability_id=%d",$row->id)),'action_state'=>'confirmation_rendered','resolved_student_id'=>(int)$row->subject_student_id,'confirmation_digest'=>hash('sha256',$confirmation),'redemption_key_digest'=>hash('sha256',$confirmation),'request_fingerprint_digest'=>hash('sha256',wp_json_encode($_REQUEST)),'occurred_at'=>$now,'created_at'=>$now,'created_by'=>null));return array('capability_id'=>(int)$row->id,'lesson_id'=>(int)$row->lesson_id,'confirmation_token'=>$confirmation,'purpose'=>PortalRule::ABSENCE); }
    public function confirmAbsence(string $handle,string $token,string $confirmation):array { if(strlen($confirmation)!==64)throw new \InvalidArgumentException('portal_confirmation_invalid');global $wpdb;$digest=hash('sha256',$confirmation);$done=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}dzn_portal_public_action_events WHERE confirmation_digest=%s AND action_state='submitted' LIMIT 1",$digest));if($done)return array('capability_id'=>(int)$done->capability_id,'lesson_id'=>(int)$done->lesson_id,'attribution'=>'public_capability_on_behalf','state'=>'submitted','replayed'=>true);$svc=new PortalCapabilityService();$row=$svc->verify($handle,$token,PortalRule::ABSENCE);$event=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}dzn_portal_public_action_events WHERE capability_id=%d AND confirmation_digest=%s AND action_state='confirmation_rendered' ORDER BY id DESC LIMIT 1",$row->id,$digest));if(!$event)throw new \InvalidArgumentException('portal_confirmation_invalid');$subject=new PublicCapabilityReadSubject((int)$row->id,PortalRule::ABSENCE,(int)$row->lesson_id,(int)$row->schedule_version_id,(int)$row->generation,(int)$row->subject_student_id,(string)$row->expires_at);$result=PortalOwnerPorts::attendance()->submitCapabilityClaim($subject,$confirmation);$now=gmdate('Y-m-d H:i:s');$wpdb->insert($wpdb->prefix.'dzn_portal_public_action_events',array('uid'=>substr(hash('sha256',wp_generate_uuid4()),0,26),'capability_id'=>(int)$row->id,'lesson_id'=>(int)$row->lesson_id,'purpose'=>PortalRule::ABSENCE,'action_sequence'=>(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(action_sequence),0)+1 FROM {$wpdb->prefix}dzn_portal_public_action_events WHERE capability_id=%d",$row->id)),'action_state'=>'submitted','resolved_student_id'=>(int)$row->subject_student_id,'confirmation_digest'=>$digest,'redemption_key_digest'=>$digest,'handoff_target'=>'canonical_attendance_evidence','handoff_reference_id'=>(int)$result['case_id'],'request_fingerprint_digest'=>hash('sha256',wp_json_encode($_REQUEST)),'outcome_reason_code'=>null,'occurred_at'=>$now,'created_at'=>$now,'created_by'=>null));$wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}dzn_portal_public_capabilities SET state='consumed',active_slot=NULL,consumed_at=%s,consumed_action_event_id=%d WHERE id=%d AND state='active'",$now,$event->id,$row->id));return array_merge($result,array('capability_id'=>(int)$row->id,'attribution'=>'public_capability_on_behalf','state'=>'submitted')); }
}
